// Normaliza el mensaje entrante de WhatsApp (soporta Twilio y Meta).
const raw = $input.first().json || {};
let telefono = '';
let mensaje = '';
// Meta Cloud API
const m0 = raw.entry && raw.entry[0] && raw.entry[0].changes && raw.entry[0].changes[0] && raw.entry[0].changes[0].value && raw.entry[0].changes[0].value.messages && raw.entry[0].changes[0].value.messages[0];
if (m0) {
  telefono = m0.from || '';
  mensaje = (m0.text && m0.text.body) || '';
}
// Twilio
if (!telefono) telefono = raw.from || raw.From || '';
if (!mensaje) mensaje = raw.body || raw.Body || '';
return [{ json: { telefono, mensaje } }];

// Construye el prompt del chatbot de WhatsApp con el contexto de la persona.
const ctx = $input.first().json; // respuesta del backend (whatsapp/contexto)
const datos = $('Extraer mensaje').first().json;
let contextoTexto;
if (ctx && ctx.autenticado) {
  const rolNombre = { usuario: 'usuario adoptante', refugio: 'representante de refugio', empleado_refugio: 'empleado de refugio', tienda_aliada: 'miembro de tienda aliada', administrador: 'administrador' }[ctx.rol] || ctx.rol;
  contextoTexto = 'Persona AUTENTICADA por su telefono WhatsApp. Rol: ' + rolNombre + '. Nombre: ' + (ctx.usuario ? (ctx.usuario.nombre || '') : '') + '.\n';
  const pedidos = Array.isArray(ctx.pedidos) ? ctx.pedidos : [];
  contextoTexto += (pedidos.length ? 'Sus pedidos:\n' + pedidos.map((p) => '- ' + (p.numero || p.id) + ': ' + (p.estado_nombre || p.estado || '?')).join('\n') + '\n' : 'Sus pedidos: (sin pedidos)\n');
  const adop = Array.isArray(ctx.adopciones) ? ctx.adopciones : [];
  contextoTexto += (adop.length ? 'Sus adopciones:\n' + adop.map((a) => '- ' + a.mascota + ': ' + a.estado).join('\n') + '\n' : 'Sus adopciones: (sin adopciones)\n');
  if (ctx.tienda) contextoTexto += 'Su tienda: ' + ctx.tienda.nombre + '\n';
  if (ctx.refugio) contextoTexto += 'Su refugio: ' + ctx.refugio.nombre + '\n';
} else {
  contextoTexto = 'Persona NO identificada (su numero WhatsApp no esta registrado en Adoptify). Puede hacer preguntas generales (que es la pagina, cuidados de mascotas, como adoptar, refugios, tienda, foro). Si pide datos personales (estado de pedidos, adopciones) o de su tienda/refugio, pidele que use el numero de telefono con el que se registro en la pagina, o que se registre en la web e ingrese ese numero. No inventes datos.';
}
const instruccion = 'Eres el asistente por WhatsApp de Adoptify, una plataforma de adopcion de mascotas que conecta refugios, tiendas aliadas y adoptantes. Respondes en espanol, de forma clara y amable, con texto plano (sin markdown). Puedes responder dudas generales sobre la plataforma, el proceso de adopcion, cuidados de mascotas, refugios, tienda, foro y dar sugerencias utiles sobre mascotas. IMPORTANTE ROL: Conoces el rol de la persona por el CONTEXTO. Si es una tienda y pregunta por pedidos o productos, responde con base al contexto de su tienda (y aclara que los detalles de stock se ven en su panel). Si es un refugio, responde segun su contexto. Si NO esta autenticada y pide algo personal, pidele que use su numero registrado o que se registre. No inventes datos ni consultes nada fuera de lo dado.\n\n';
const prompt = instruccion + 'CONTEXTO DE LA PERSONA:\n' + contextoTexto + '\n\nMENSAJE DEL USUARIO:\n' + (datos.mensaje || '');
return [{ json: { prompt } }];

// Extrae el texto de respuesta del AI Agent.
const r = $input.all()[0].json;
let texto = (typeof r.output === 'string') ? r.output : (r.output ? JSON.stringify(r.output) : '');
texto = String(texto || '').trim();
if (!texto) texto = 'Hola! Soy el asistente de Adoptify por WhatsApp. Preguntame que necesites.';
return [{ json: { respuesta: texto } }];

// Prepara la llamada al proveedor (Twilio o Meta) con la respuesta del bot.
const r = $input.first().json; // {respuesta}
const prov = ($env.WHATSAPP_PROVIDER || 'twilio').toLowerCase();
const telefono = String(r.telefono || '').replace(/^\+/, '');
const mensaje = String(r.respuesta || '');
let url = '';
let headers = {};
let meta = null;
let twilio = null;
if (prov === 'meta') {
  url = 'https://graph.facebook.com/' + ($env.META_WHATSAPP_VERSION || 'v20.0') + '/' + $env.META_WHATSAPP_PHONE_ID + '/messages';
  headers = { Authorization: 'Bearer ' + $env.META_WHATSAPP_TOKEN };
  meta = { messaging_product: 'whatsapp', to: telefono, type: 'text', text: { body: mensaje } };
} else {
  url = 'https://api.twilio.com/2010-04-01/Accounts/' + $env.TWILIO_ACCOUNT_SID + '/Messages.json';
  headers = { Authorization: 'Basic ' + Buffer.from($env.TWILIO_ACCOUNT_SID + ':' + $env.TWILIO_AUTH_TOKEN).toString('base64') };
  twilio = { From: $env.TWILIO_WHATSAPP_FROM, To: 'whatsapp:' + telefono, Body: mensaje };
}
return [{ json: { provider: prov, url, headers, meta, twilio } }];
